from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    """
    This function takes a string containing multiple groups of nested parentheses as input, 
    and returns a list of strings where each group of parentheses is separated into separate strings.

    Args:
        paren_string (str): A string containing multiple groups of nested parentheses.

    Returns:
        List[str]: A list of strings where each group of parentheses is separated into separate strings.
    """
    stack = []
    result = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            stack.append(char)
            current_group += char
        elif char == ")":
            if stack:
                result.append(current_group)
                current_group = ""
                stack.pop()
        elif char.isspace():
            if stack:
                current_group += char
        else:
            if not stack:
                raise ValueError("Unbalanced parentheses")

    if current_group:
        result.append(current_group)

    return result
